---SetNodeInfo
---设置假象实战关卡信息
function UIBattleEndVirtualTrainingInfo:SetNodeInfo()
    local showData = BattleEndMgr.showData
    local questId = BattleEndMgr.questId
    local questVo = QuestConfMgr:GetQuestVoById(questId)
    --- Boss 头像
    if not IsNull(questVo) then
        local monsterId = checkNumber(questVo.monsterShow)
        local bossVo = CardConfMgr:GetInstance():GetMonsterTypeVoById(checkNumber(monsterId))
        if bossVo then
            local skinId = bossVo.skinId
            local skinData = UIBattlingTools.GetCardSkinDataBySkinId(skinId)
            if skinData then
                self.Img_BossHead:LoadSprite(skinData.buffHead)
            end
        end
    end
    if IsNull(showData) or (not isSet(showData, "response")) then return end
    local GCQConstants = import("Game.UI.FightReady.FightEnter.GachaCoinQuest.GachaCoinQuestConstants")
    local GCQUtils = import(GCQConstants.Path.Utils)
    --- Boss 等级
    local defLv = showData.response.copyLevel or checkNumber(GCQUtils.GetHomeDojo().copyLevel)
    self.Txt_Lv.text = defLv
    --- Boss 血条 Process
    local bossHpLast = (not isSet(showData, "response") or not isSet(showData.response, "bossHpPercent") or checkNumber(showData.response.bossHpPercent) <= 0) and 0 or showData.response.bossHpPercent
    self.slider.value = checkNumber(bossHpLast)
    --- Boss 血条 Text
    local valueEx = GCQUtils.GetHomeDojo().bossHpPercent
    local damageValue = Mathf.Floor((valueEx - bossHpLast) * 10000) * 0.01
    self.Txt_DamageValue.text = string.format("%0.2f%%", damageValue)
end

------------ DataFunction ------------

return UIBattleEndVirtualTrainingInfo